head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.btnPop_onclick = function(e) {
    var options = {
        id: "popup1",
        type: "wframePopup",
        width: "230px",
        height: "250px",
        top: "130px",
        left: "200px",
        popupName: "openPopup1",
        modal: true,
        useModalStack: true,
        alwaysOnTop: false,
        resizable: true,
        status: true,
        menubar: false,
        scrollbars: false,
        title: false,
        closeAction: "scwin.callback"
    };
    scwin.$w.openPopup("popup_popWin_WEFF-285_(WSQ-3549)_sub.xml", options);
};
scwin.callback = function() {
    console.log("closeAction Callback");
    var options = {
        id: "popup2",
        type: "wframePopup",
        width: "230px",
        height: "250px",
        top: "130px",
        left: "500px",
        popupName: "openPopup1",
        modal: true,
        useModalStack: true,
        alwaysOnTop: false,
        resizable: true,
        status: true,
        menubar: false,
        scrollbars: false,
        title: false,
        closeAction: "scwin.callback2"
    };
    scwin.$w.openPopup("popup_popWin_WEFF-285_(WSQ-3549)_sub.xml", options);
    return true;
};
scwin.checkLog = function() {
    return WebSquare.logger.getErrorLog();
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 1. 샘플파일을 실행 후 상단의 그리드(options.closeGroup = false; 일경우)와 하단의 그리드(options.closeGroup = true; 일경우) 대리점항목명을 마우스로 드래그하여 위로 끌어다 놓는다. 
    //1. Run the sample file and drag it to the top grid (if options.closeGroup = false;) and the bottom grid (if options.closeGroup = true;
    //Verify step 1. The upper grid and the lower grid are grouped by the agency name and the time (duration 370 ms) is shown.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btnPop').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('popup1_wframe_btnClose').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('popup2_wframe_btnClose').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkLog() == ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    requires("uiplugin.popup");
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
